/**
 * Migrations run as the admin role (the only one that can create schemas, roles and policies).
 * The drizzle/ folder holds those generated by drizzle-kit from schema.ts and the hand-written
 * ones (roles, RLS, privileges); they apply in order, once each. Then it seeds the prompts from
 * prompts/ into the database, also idempotently.
 */
import { fileURLToPath } from 'node:url'
import { migrate } from 'drizzle-orm/node-postgres/migrator'
import { connect } from './client.ts'
import { syncPromptFiles, type PromptSyncReport } from './prompts.ts'

export const MIGRATIONS_DIR = fileURLToPath(new URL('../drizzle', import.meta.url))

export async function runMigrations(adminUrl: string): Promise<PromptSyncReport> {
  const conn = connect(adminUrl, { max: 1 })
  try {
    await migrate(conn.db, { migrationsFolder: MIGRATIONS_DIR, migrationsSchema: 'drizzle' })
    return await syncPromptFiles(conn.db)
  } finally {
    await conn.close()
  }
}
